\draw[black,dashed] (0,3.25) -- (8,3.25);
\draw[modelblue,thick,domain=0:8,samples=121,variable=\x] plot ({\x},{2.5+1.5*cos(45*(\x))});
\foreach \t in {1.333333,6.666667}{\draw[black,dashed] (\t,0) -- (\t,3.25);\fill[black] (\t,3.25) circle (1.2pt);}
\path (1.333333,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\frac43$};
\path (6.666667,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\frac{20}{3}$};
\draw[black] (8,-0.1) -- (8,0.1);
\path (8,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$8$};
